bg=3
motifs={5:[[1,1,0],[0,0,1],[0,1,1]],7:[[1,1,1],[1,0,1],[0,1,0]],6:[[1,1,0],[0,1,0],[1,1,1]],9:[[1,1,1],[0,1,0],[1,0,1]],4:[[1,0,0],[0,1,1],[1,0,0]],2:[[1,0,0],[0,1,1],[0,0,1]]}
layout=[[5,7],[6,9],[4,2]]
out=[[bg]*13 for _ in range(19)]
for pr,row in enumerate(layout):
 for pc,col in enumerate(row):
  r0=1+pr*6;c0=1+pc*6
  for dr in range(5):
   for dc in range(5):
    if dr in (0,4) or dc in (0,4): val=col
    else: val=bg if motifs[col][dr-1][dc-1] else col
    out[r0+dr][c0+dc]=val
print('\n'.join(' '.join(map(str,row)) for row in out))

motifs[5]=[[1,1,0],[0,1,0],[0,1,1]]
out=[[bg]*13 for _ in range(19)]
for pr,row in enumerate(layout):
 for pc,col in enumerate(row):
  r0=1+pr*6;c0=1+pc*6
  for dr in range(5):
   for dc in range(5):
    out[r0+dr][c0+dc]=col if dr in (0,4) or dc in (0,4) else (bg if motifs[col][dr-1][dc-1] else col)
print('\n'.join(' '.join(map(str,r)) for r in out))
